import sys

class ComplexNumber:
    def __init__(self, real, imag):
        self.real = real
        self.imag = imag

def add(c1, c2):
    return ComplexNumber(c1.real + c2.real, c1.imag + c2.imag)

def sub(c1, c2):
    return ComplexNumber(c1.real - c2.real, c1.imag - c2.imag)

def mul(c1, c2):
    real = c1.real * c2.real - c1.imag * c2.imag
    imag = c1.real * c2.imag + c1.imag * c2.real
    return ComplexNumber(real, imag)

def div(c1, c2):
    denom = c2.real * c2.real + c2.imag * c2.imag
    real = (c1.real * c2.real + c1.imag * c2.imag) / denom
    imag = (c1.imag * c2.real - c1.real * c2.imag) / denom
    return ComplexNumber(real, imag)

def fmt(c):
    sign = '+' if c.imag >= 0 else '-'
    return f"{c.real:.2f} {sign} {abs(c.imag):.2f}i"

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if len(lines) < 2:
        return
    a = list(map(int, lines[0].split()))
    b = list(map(int, lines[1].split()))
    c1 = ComplexNumber(a[0], a[1])
    c2 = ComplexNumber(b[0], b[1])
    print(f"Addition: {fmt(add(c1, c2))}")
    print(f"Subtraction: {fmt(sub(c1, c2))}")
    print(f"Multiplication: {fmt(mul(c1, c2))}")
    print(f"Division: {fmt(div(c1, c2))}")

if __name__ == "__main__":
    main()
